// ============================================================================
// PII Redaction
// ============================================================================

const PII_PATTERNS = [
  /\b\d{3}-\d{2}-\d{4}\b/g,                    // SSN
  /\b[A-Z]{2}\d{6,9}\b/g,                       // Passport
  /\b\d{4}[\s-]?\d{4}[\s-]?\d{4}[\s-]?\d{4}\b/g, // Credit card
  /patient[_\s]?(?:id|name|mrn)/gi,              // Patient identifiers
];

function redactPii(value: string): string {
  let result = value;
  for (const pattern of PII_PATTERNS) {
    result = result.replace(pattern, '[REDACTED]');
  }
  return result;
}

function redactObject(obj: Record<string, unknown>, governance: GovernanceConfig): Record<string, unknown> {
  if (!governance.pii_redaction) return obj;
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(obj)) {
    if (typeof value === 'string') {
      result[key] = redactPii(value);
    } else if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
      result[key] = redactObject(value as Record<string, unknown>, governance);
    } else {
      result[key] = value;
    }
  }
  return result;
}

// ============================================================================
// InforMapper — Domain ↔ Wire Type Translation
